"use strict";
// A plain package scriptc compiles natively that requires an island package.
const islandlib = require("islandlib");

// A binding the module reassigns after requiring: reads follow the binding.
let swappable = require("islandlib");
swappable = { makeCounter: () => ({ inc: () => 100 }) };
exports.swapped = () => swappable.makeCounter(0).inc();
exports.localName = require("./local").localName;

exports.twice = function twice(start) {
  const c = islandlib.makeCounter(start);
  c.inc();
  return c.inc();
};
